package in.aicon.pocket;
import android.content.*;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.util.*;import java.io.IOException;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class ResetCoordinatorTest {
 SQLiteDatabase db;String subject="678901234567890123456";ResetIntentStore intents;Fake remote;ResetCoordinator coordinator;
 static class Fake implements ResetCoordinator.Remote {Map<String,String> markers=new LinkedHashMap<>(),files=new LinkedHashMap<>();boolean lostPublish,failDelete;int reservations,publishes;public Map<String,String> resetMarkers(){return new LinkedHashMap<>(markers);}public Map<String,String> operationFiles(){return new LinkedHashMap<>(files);}public String reserveFileId(){return "reserved_"+(++reservations);}public void appendFile(String id,String body){files.put(id,body);}public void publishReset(String file,String id)throws Exception{String value=ResetWire.marker(id),old=markers.putIfAbsent(file,value);if(old!=null&&!old.equals(value))throw new IllegalStateException("Collision");publishes++;if(lostPublish){lostPublish=false;throw new IOException("Response lost after commit");}}public void deleteOperationFile(String file)throws Exception{if(failDelete)throw new IOException("Delete unavailable");files.remove(file);}}
 @Before public void setup()throws Exception{Context c=RuntimeEnvironment.getApplication();c.deleteDatabase(AccountScope.databaseFor(subject));db=c.openOrCreateDatabase(AccountScope.databaseFor(subject),0,null);new LedgerSyncStore(db,subject);db.execSQL("INSERT INTO tx(uuid,kind,amount,day,account,dest,category,note) VALUES('11111111-1111-4111-8111-111111111111','income',100,'2026-11-11','Cash','','Food','private')");intents=new ResetIntentStore(db,subject);remote=new Fake();coordinator=new ResetCoordinator(db,subject,remote,()->{});SyncEngine.Pending old=new SyncEngine.Pending(UUID.randomUUID().toString(),"old_file",new SyncModel.Record(UUID.randomUUID().toString(),"financial content",false,Collections.singletonMap("device",1L)));remote.files.put("old_file",ResetWire.operation(old,new ResetBarrier.View(Collections.emptySet())));}
 @After public void close(){db.close();}
 long count(String table){try(Cursor c=db.rawQuery("SELECT count(*) FROM "+table,null)){c.moveToFirst();return c.getLong(0);}}
 @Test public void lostPublishResponseRetriesSameMarkerAndReservation()throws Exception{String id=UUID.randomUUID().toString();intents.begin(id);remote.lostPublish=true;try{coordinator.resume();fail();}catch(IOException expected){}assertEquals("publish",intents.current().phase);assertEquals(1,count("tx"));assertEquals(1,remote.markers.size());assertEquals(1,coordinator.resume());assertNull(intents.current());assertEquals(0,count("tx"));assertEquals(1,remote.reservations);assertEquals(2,remote.publishes);assertEquals(1,remote.markers.size());assertTrue(remote.files.isEmpty());assertTrue(new ResetStore(db,subject).view().known.contains(id));}
 @Test public void failedCleanupRetainsIntentAndDoesNotRepublishOrResurrect()throws Exception{intents.begin(UUID.randomUUID().toString());remote.failDelete=true;try{coordinator.resume();fail();}catch(IOException expected){}assertEquals("cleanup",intents.current().phase);assertEquals(0,count("tx"));assertEquals(1,remote.files.size());remote.failDelete=false;assertEquals(1,coordinator.resume());assertNull(intents.current());assertEquals(1,remote.publishes);assertEquals(1,remote.reservations);assertEquals(0,count("tx"));}
 @Test public void noIntentOrAccountGuardPreventsAnyRemoteMutation()throws Exception{try{coordinator.resume();fail();}catch(IllegalStateException expected){}assertEquals(0,remote.publishes);intents.begin(UUID.randomUUID().toString());try{new ResetCoordinator(db,subject,remote,()->{throw new IllegalStateException("Account switched");}).resume();fail();}catch(IllegalStateException expected){}assertEquals(0,remote.publishes);assertEquals(1,count("tx"));}
}
